/**
 * Role-Based Access Control (RBAC)
 *
 * Permission and role management for SAGE applications.
 */

/**
 * Role definition
 */
export interface Role {
  /** Role name (unique identifier) */
  name: string;

  /** Human-readable description */
  description?: string;

  /** Permissions granted by this role */
  permissions: string[];

  /** Roles this role inherits from */
  inherits?: string[];
}

/**
 * RBAC configuration
 */
export interface RBACConfig {
  /** Available roles */
  roles: Role[];

  /** Default role for new users */
  defaultRole?: string;

  /** Super admin role name (has all permissions) */
  superAdminRole?: string;
}

/**
 * User with roles
 */
export interface RBACUser {
  /** User ID */
  id: string;

  /** User's roles */
  roles: string[];

  /** Direct permissions (in addition to role permissions) */
  permissions?: string[];
}

/**
 * Authorization result
 */
export interface AuthorizationResult {
  /** Whether access is granted */
  allowed: boolean;

  /** Reason for denial (if denied) */
  reason?: string;

  /** Missing permissions (if denied) */
  missingPermissions?: string[];
}

/**
 * Create an RBAC manager
 */
export function createRBAC(config: RBACConfig) {
  const roleMap = new Map<string, Role>();
  const permissionCache = new Map<string, Set<string>>();

  // Index roles
  for (const role of config.roles) {
    roleMap.set(role.name, role);
  }

  /**
   * Get all permissions for a role (including inherited)
   */
  function getRolePermissions(roleName: string, visited = new Set<string>()): Set<string> {
    // Check cache
    const cached = permissionCache.get(roleName);
    if (cached) return cached;

    // Prevent circular inheritance
    if (visited.has(roleName)) {
      return new Set();
    }
    visited.add(roleName);

    const role = roleMap.get(roleName);
    if (!role) {
      return new Set();
    }

    const permissions = new Set(role.permissions);

    // Add inherited permissions
    if (role.inherits) {
      for (const inheritedRole of role.inherits) {
        const inheritedPerms = getRolePermissions(inheritedRole, visited);
        for (const perm of inheritedPerms) {
          permissions.add(perm);
        }
      }
    }

    // Cache result
    permissionCache.set(roleName, permissions);
    return permissions;
  }

  /**
   * Get all permissions for a user
   */
  function getUserPermissions(user: RBACUser): Set<string> {
    const permissions = new Set<string>();

    // Check for super admin role
    if (config.superAdminRole && user.roles.includes(config.superAdminRole)) {
      // Super admin has all permissions - return special marker
      permissions.add('*');
      return permissions;
    }

    // Add permissions from roles
    for (const roleName of user.roles) {
      const rolePerms = getRolePermissions(roleName);
      for (const perm of rolePerms) {
        permissions.add(perm);
      }
    }

    // Add direct permissions
    if (user.permissions) {
      for (const perm of user.permissions) {
        permissions.add(perm);
      }
    }

    return permissions;
  }

  /**
   * Check if user has a specific permission
   */
  function hasPermission(user: RBACUser, permission: string): boolean {
    const permissions = getUserPermissions(user);

    // Super admin check
    if (permissions.has('*')) {
      return true;
    }

    // Direct check
    if (permissions.has(permission)) {
      return true;
    }

    // Wildcard check (e.g., "users:*" matches "users:read")
    const parts = permission.split(':');
    for (let i = parts.length - 1; i > 0; i--) {
      const wildcard = parts.slice(0, i).join(':') + ':*';
      if (permissions.has(wildcard)) {
        return true;
      }
    }

    return false;
  }

  /**
   * Check if user has all of the specified permissions
   */
  function hasAllPermissions(user: RBACUser, permissions: string[]): boolean {
    return permissions.every(p => hasPermission(user, p));
  }

  /**
   * Check if user has any of the specified permissions
   */
  function hasAnyPermission(user: RBACUser, permissions: string[]): boolean {
    return permissions.some(p => hasPermission(user, p));
  }

  /**
   * Check if user has a specific role
   */
  function hasRole(user: RBACUser, roleName: string): boolean {
    return user.roles.includes(roleName);
  }

  /**
   * Check if user has any of the specified roles
   */
  function hasAnyRole(user: RBACUser, roleNames: string[]): boolean {
    return roleNames.some(r => hasRole(user, r));
  }

  return {
    /**
     * Get all roles
     */
    getRoles(): Role[] {
      return config.roles;
    },

    /**
     * Get a role by name
     */
    getRole(name: string): Role | undefined {
      return roleMap.get(name);
    },

    /**
     * Get the default role
     */
    getDefaultRole(): Role | undefined {
      return config.defaultRole ? roleMap.get(config.defaultRole) : undefined;
    },

    /**
     * Get all permissions for a role
     */
    getRolePermissions,

    /**
     * Get all permissions for a user
     */
    getUserPermissions,

    /**
     * Check if user has permission
     */
    hasPermission,

    /**
     * Check if user has all permissions
     */
    hasAllPermissions,

    /**
     * Check if user has any permission
     */
    hasAnyPermission,

    /**
     * Check if user has role
     */
    hasRole,

    /**
     * Check if user has any role
     */
    hasAnyRole,

    /**
     * Require a permission (throws if denied)
     */
    requirePermission(user: RBACUser, permission: string): void {
      if (!hasPermission(user, permission)) {
        throw new AuthorizationError(`Missing permission: ${permission}`, [permission]);
      }
    },

    /**
     * Require all permissions (throws if any denied)
     */
    requireAllPermissions(user: RBACUser, permissions: string[]): void {
      const missing = permissions.filter(p => !hasPermission(user, p));
      if (missing.length > 0) {
        throw new AuthorizationError(`Missing permissions: ${missing.join(', ')}`, missing);
      }
    },

    /**
     * Require any permission (throws if all denied)
     */
    requireAnyPermission(user: RBACUser, permissions: string[]): void {
      if (!hasAnyPermission(user, permissions)) {
        throw new AuthorizationError(
          `Missing at least one of: ${permissions.join(', ')}`,
          permissions
        );
      }
    },

    /**
     * Require a role (throws if denied)
     */
    requireRole(user: RBACUser, roleName: string): void {
      if (!hasRole(user, roleName)) {
        throw new AuthorizationError(`Missing role: ${roleName}`);
      }
    },

    /**
     * Require any role (throws if all denied)
     */
    requireAnyRole(user: RBACUser, roleNames: string[]): void {
      if (!hasAnyRole(user, roleNames)) {
        throw new AuthorizationError(`Missing at least one role: ${roleNames.join(', ')}`);
      }
    },

    /**
     * Authorize with detailed result
     */
    authorize(user: RBACUser, permission: string): AuthorizationResult {
      if (hasPermission(user, permission)) {
        return { allowed: true };
      }
      return {
        allowed: false,
        reason: 'Permission denied',
        missingPermissions: [permission],
      };
    },

    /**
     * Clear the permission cache (call after role changes)
     */
    clearCache(): void {
      permissionCache.clear();
    },
  };
}

/**
 * Authorization error
 */
export class AuthorizationError extends Error {
  public readonly missingPermissions?: string[];

  constructor(message: string, missingPermissions?: string[]) {
    super(message);
    this.name = 'AuthorizationError';
    this.missingPermissions = missingPermissions;
  }
}

/**
 * Common permission patterns
 */
export const Permissions = {
  // Resource CRUD pattern
  create: (resource: string) => `${resource}:create`,
  read: (resource: string) => `${resource}:read`,
  update: (resource: string) => `${resource}:update`,
  delete: (resource: string) => `${resource}:delete`,
  list: (resource: string) => `${resource}:list`,
  all: (resource: string) => `${resource}:*`,

  // Common permissions
  ADMIN: 'admin',
  SUPER_ADMIN: '*',
} as const;

/**
 * Helper to define roles
 */
export function defineRole(
  name: string,
  permissions: string[],
  options?: { description?: string; inherits?: string[] }
): Role {
  return {
    name,
    permissions,
    description: options?.description,
    inherits: options?.inherits,
  };
}

/**
 * Create common role presets
 */
export function createCommonRoles() {
  return {
    viewer: defineRole('viewer', [
      Permissions.read('*'),
      Permissions.list('*'),
    ], { description: 'Can view all resources' }),

    editor: defineRole('editor', [
      Permissions.create('*'),
      Permissions.update('*'),
    ], {
      description: 'Can create and edit resources',
      inherits: ['viewer'],
    }),

    admin: defineRole('admin', [
      Permissions.delete('*'),
      'admin',
    ], {
      description: 'Full access to all resources',
      inherits: ['editor'],
    }),

    superAdmin: defineRole('super_admin', ['*'], {
      description: 'Super administrator with all permissions',
    }),
  };
}
