/**
 * API Key Authentication
 *
 * Server-to-server authentication using API keys.
 * Supports key generation, hashing, and validation.
 */

import { createHash, randomBytes } from 'crypto';

/**
 * API key configuration
 */
export interface APIKeyConfig {
  /** Hash algorithm (default: sha256) */
  hashAlgorithm?: 'sha256' | 'sha384' | 'sha512';

  /** Key prefix for identification (e.g., "sk_") */
  prefix?: string;

  /** Key length in bytes (default: 32) */
  keyLength?: number;
}

/**
 * API key with metadata
 */
export interface APIKey {
  /** Unique key ID */
  id: string;

  /** Key prefix portion (safe to show) */
  prefix: string;

  /** Hashed key value (for storage) */
  hash: string;

  /** Associated user/service ID */
  userId: string;

  /** Key name/label */
  name: string;

  /** Permissions granted to this key */
  permissions: string[];

  /** Expiration timestamp (optional) */
  expiresAt?: number;

  /** Creation timestamp */
  createdAt: number;

  /** Last used timestamp */
  lastUsedAt?: number;

  /** Whether the key is revoked */
  revoked?: boolean;
}

/**
 * Result of API key generation
 */
export interface APIKeyGenerationResult {
  /** The full key (only shown once!) */
  key: string;

  /** The key record (for storage) */
  record: APIKey;
}

/**
 * API key store interface
 */
export interface APIKeyStore {
  /** Store a new API key */
  store(key: APIKey): Promise<void>;

  /** Find a key by its hash */
  findByHash(hash: string): Promise<APIKey | null>;

  /** Find a key by ID */
  findById(id: string): Promise<APIKey | null>;

  /** Update key (e.g., lastUsedAt) */
  update(id: string, updates: Partial<APIKey>): Promise<void>;

  /** Delete/revoke a key */
  revoke(id: string): Promise<void>;

  /** List keys for a user */
  listByUser(userId: string): Promise<APIKey[]>;
}

/**
 * In-memory API key store (for testing/development)
 */
export class InMemoryAPIKeyStore implements APIKeyStore {
  private keys = new Map<string, APIKey>();
  private hashIndex = new Map<string, string>();

  async store(key: APIKey): Promise<void> {
    this.keys.set(key.id, key);
    this.hashIndex.set(key.hash, key.id);
  }

  async findByHash(hash: string): Promise<APIKey | null> {
    const id = this.hashIndex.get(hash);
    if (!id) return null;
    return this.keys.get(id) ?? null;
  }

  async findById(id: string): Promise<APIKey | null> {
    return this.keys.get(id) ?? null;
  }

  async update(id: string, updates: Partial<APIKey>): Promise<void> {
    const key = this.keys.get(id);
    if (key) {
      this.keys.set(id, { ...key, ...updates });
    }
  }

  async revoke(id: string): Promise<void> {
    const key = this.keys.get(id);
    if (key) {
      // Keep the hash in the index so we can still look it up and return "revoked" error
      key.revoked = true;
      this.keys.set(id, key);
    }
  }

  async listByUser(userId: string): Promise<APIKey[]> {
    return Array.from(this.keys.values()).filter(k => k.userId === userId && !k.revoked);
  }
}

/**
 * Default configuration
 */
const DEFAULT_CONFIG: Required<APIKeyConfig> = {
  hashAlgorithm: 'sha256',
  prefix: 'sk_',
  keyLength: 32,
};

/**
 * Generate a new API key
 */
export function generateAPIKey(
  userId: string,
  name: string,
  permissions: string[] = [],
  options?: APIKeyConfig & { expiresIn?: number }
): APIKeyGenerationResult {
  const config = { ...DEFAULT_CONFIG, ...options };

  // Generate random key bytes
  const keyBytes = randomBytes(config.keyLength);
  const keyBase64 = keyBytes.toString('base64url');

  // Create full key with prefix
  const fullKey = `${config.prefix}${keyBase64}`;

  // Hash the key for storage
  const hash = hashAPIKey(fullKey, config.hashAlgorithm);

  // Generate unique ID
  const id = randomBytes(16).toString('hex');

  // Calculate expiration if specified
  const expiresAt = options?.expiresIn 
    ? Date.now() + options.expiresIn * 1000
    : undefined;

  const record: APIKey = {
    id,
    prefix: `${config.prefix}${keyBase64.slice(0, 8)}...`,
    hash,
    userId,
    name,
    permissions,
    expiresAt,
    createdAt: Date.now(),
  };

  return { key: fullKey, record };
}

/**
 * Hash an API key for storage
 */
export function hashAPIKey(
  key: string,
  algorithm: 'sha256' | 'sha384' | 'sha512' = 'sha256'
): string {
  return createHash(algorithm).update(key).digest('hex');
}

/**
 * Validate an API key
 */
export async function validateAPIKey(
  key: string,
  store: APIKeyStore,
  algorithm: 'sha256' | 'sha384' | 'sha512' = 'sha256'
): Promise<{ valid: boolean; key?: APIKey; error?: string }> {
  // Hash the provided key
  const hash = hashAPIKey(key, algorithm);

  // Look up by hash
  const record = await store.findByHash(hash);

  if (!record) {
    return { valid: false, error: 'Invalid API key' };
  }

  // Check if revoked
  if (record.revoked) {
    return { valid: false, error: 'API key has been revoked' };
  }

  // Check expiration
  if (record.expiresAt && record.expiresAt < Date.now()) {
    return { valid: false, error: 'API key has expired' };
  }

  // Update last used time
  await store.update(record.id, { lastUsedAt: Date.now() });

  return { valid: true, key: record };
}

/**
 * Create an API key authenticator
 */
export function createAPIKeyAuth(
  store: APIKeyStore,
  config?: APIKeyConfig
) {
  const hashAlgorithm = config?.hashAlgorithm ?? 'sha256';

  return {
    /**
     * Generate a new API key
     */
    generate(
      userId: string,
      name: string,
      permissions: string[] = [],
      options?: { expiresIn?: number }
    ): Promise<APIKeyGenerationResult> {
      const result = generateAPIKey(userId, name, permissions, { ...config, ...options });
      return store.store(result.record).then(() => result);
    },

    /**
     * Validate an API key from request
     */
    async validate(key: string): Promise<{ valid: boolean; key?: APIKey; error?: string }> {
      return validateAPIKey(key, store, hashAlgorithm);
    },

    /**
     * Extract API key from request headers
     */
    extractFromRequest(request: Request): string | null {
      // Check Authorization header (Bearer token)
      const authHeader = request.headers.get('Authorization');
      if (authHeader?.startsWith('Bearer ')) {
        const token = authHeader.slice(7);
        if (token.startsWith(config?.prefix ?? 'sk_')) {
          return token;
        }
      }

      // Check X-API-Key header
      const apiKeyHeader = request.headers.get('X-API-Key');
      if (apiKeyHeader) {
        return apiKeyHeader;
      }

      return null;
    },

    /**
     * Revoke an API key
     */
    revoke(keyId: string): Promise<void> {
      return store.revoke(keyId);
    },

    /**
     * List keys for a user
     */
    listKeys(userId: string): Promise<APIKey[]> {
      return store.listByUser(userId);
    },
  };
}

/**
 * Create auth middleware for API keys
 */
export function createAPIKeyMiddleware(
  store: APIKeyStore,
  config?: APIKeyConfig
) {
  const auth = createAPIKeyAuth(store, config);

  return async (request: Request): Promise<{
    authenticated: boolean;
    userId?: string;
    permissions?: string[];
    error?: string;
  }> => {
    const key = auth.extractFromRequest(request);

    if (!key) {
      return { authenticated: false, error: 'No API key provided' };
    }

    const result = await auth.validate(key);

    if (!result.valid || !result.key) {
      return { authenticated: false, error: result.error };
    }

    return {
      authenticated: true,
      userId: result.key.userId,
      permissions: result.key.permissions,
    };
  };
}
