/**
 * Auth Middleware
 *
 * Generic auth middleware interface and utilities for protecting SAGE handlers.
 * Supports multiple auth providers through adapters.
 */

import type { AuthUser, AuthSession } from './types';

/**
 * Authenticated user info extracted from request
 */
export interface AuthenticatedUser {
  id: string;
  email?: string;
  name?: string;
}

/**
 * Auth middleware result
 */
export interface AuthResult {
  authenticated: boolean;
  user?: AuthenticatedUser;
  session?: AuthSession;
  error?: string;
}

/**
 * Auth middleware function type
 *
 * Takes a request and returns auth result.
 * Implementations can extract auth from headers, cookies, etc.
 */
export type AuthMiddleware = (request: Request) => Promise<AuthResult>;

/**
 * Options for creating an auth middleware wrapper
 */
export interface AuthMiddlewareOptions {
  /** The auth middleware function */
  middleware: AuthMiddleware;

  /** Allow unauthenticated requests (default: false) */
  optional?: boolean;

  /** Custom error handler */
  onAuthError?: (error: string) => Response;
}

/**
 * Default error response for auth failures
 */
function defaultAuthErrorResponse(error: string): Response {
  return new Response(
    JSON.stringify({ error: 'Unauthorized', message: error }),
    { status: 401, headers: { 'Content-Type': 'application/json' } }
  );
}

/**
 * Wrap a handler with auth middleware
 *
 * @example
 * ```typescript
 * import { withAuth, createBetterAuthMiddleware } from '@sage/core/auth';
 * import { createChatHandler } from '@sage/core';
 *
 * const authMiddleware = createBetterAuthMiddleware(auth);
 * export const POST = withAuth(createChatHandler(config), { middleware: authMiddleware });
 * ```
 */
export function withAuth(
  handler: (request: Request, user: AuthenticatedUser) => Promise<Response>,
  options: AuthMiddlewareOptions
): (request: Request) => Promise<Response> {
  const { middleware, optional = false, onAuthError = defaultAuthErrorResponse } = options;

  return async function authHandler(request: Request): Promise<Response> {
    // Run auth middleware
    const authResult = await middleware(request);

    // Check if authenticated
    if (!authResult.authenticated || !authResult.user) {
      // If auth is optional and request is unauthenticated, proceed with null user
      if (optional) {
        // Clone request with empty user header
        return handler(request, { id: 'anonymous' });
      }

      return onAuthError(authResult.error || 'Authentication required');
    }

    // Call handler with authenticated user
    return handler(request, authResult.user);
  };
}

/**
 * Extract bearer token from Authorization header
 */
export function extractBearerToken(request: Request): string | null {
  const authHeader = request.headers.get('Authorization');
  if (!authHeader?.startsWith('Bearer ')) {
    return null;
  }
  return authHeader.slice(7);
}

/**
 * Extract session token from cookies
 */
export function extractSessionCookie(request: Request, cookieName: string = 'sage-auth.session_token'): string | null {
  const cookieHeader = request.headers.get('Cookie');
  if (!cookieHeader) {
    return null;
  }

  const cookies = parseCookies(cookieHeader);
  return cookies[cookieName] || null;
}

/**
 * Parse cookie header into object
 */
function parseCookies(cookieHeader: string): Record<string, string> {
  const cookies: Record<string, string> = {};
  const pairs = cookieHeader.split(';');

  for (const pair of pairs) {
    const [name, ...rest] = pair.trim().split('=');
    if (name && rest.length > 0) {
      cookies[name] = rest.join('=');
    }
  }

  return cookies;
}

/**
 * Create a simple JWT validation middleware
 *
 * This is a basic implementation. For production, use createBetterAuthMiddleware.
 *
 * @example
 * ```typescript
 * const authMiddleware = createJWTMiddleware({
 *   secret: process.env.JWT_SECRET!,
 *   issuer: 'https://myapp.com',
 * });
 * ```
 */
export function createJWTMiddleware(options: {
  /** JWT secret for verification */
  secret: string;
  /** Expected issuer */
  issuer?: string;
  /** Expected audience */
  audience?: string;
}): AuthMiddleware {
  const { secret, issuer, audience } = options;

  return async (request: Request): Promise<AuthResult> => {
    const token = extractBearerToken(request);

    if (!token) {
      return { authenticated: false, error: 'No authorization token provided' };
    }

    try {
      // Basic JWT validation (header.payload.signature format)
      const parts = token.split('.');
      if (parts.length !== 3) {
        return { authenticated: false, error: 'Invalid token format' };
      }

      // Decode payload (base64url)
      const payloadStr = Buffer.from(parts[1], 'base64url').toString('utf-8');
      const payload = JSON.parse(payloadStr) as {
        sub: string;
        email?: string;
        name?: string;
        iss?: string;
        aud?: string;
        exp?: number;
      };

      // Check expiration
      if (payload.exp && payload.exp < Date.now() / 1000) {
        return { authenticated: false, error: 'Token expired' };
      }

      // Check issuer
      if (issuer && payload.iss !== issuer) {
        return { authenticated: false, error: 'Invalid issuer' };
      }

      // Check audience
      if (audience && payload.aud !== audience) {
        return { authenticated: false, error: 'Invalid audience' };
      }

      // Note: This does NOT verify the signature!
      // For production, use a proper JWT library or Better Auth adapter
      console.warn('[SAGE] JWT middleware: Signature verification not implemented. Use Better Auth adapter for production.');

      return {
        authenticated: true,
        user: {
          id: payload.sub,
          email: payload.email,
          name: payload.name,
        },
      };
    } catch (error) {
      return {
        authenticated: false,
        error: `Token validation failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
      };
    }
  };
}

/**
 * Create a no-op middleware that always succeeds (for testing/development)
 *
 * @example
 * ```typescript
 * const authMiddleware = process.env.NODE_ENV === 'development'
 *   ? createNoopAuthMiddleware({ id: 'dev-user', email: 'dev@example.com' })
 *   : createBetterAuthMiddleware(auth);
 * ```
 */
export function createNoopAuthMiddleware(mockUser: AuthenticatedUser): AuthMiddleware {
  return async (): Promise<AuthResult> => {
    return {
      authenticated: true,
      user: mockUser,
    };
  };
}
