/**
 * Rate Limiter
 *
 * Sliding window rate limiting for SAGE APIs.
 * Supports in-memory and Redis-based stores.
 */

/**
 * Rate limit configuration
 */
export interface RateLimitConfig {
  /** Maximum requests per window */
  maxRequests: number;

  /** Window size in milliseconds */
  windowMs: number;

  /** Key generator function */
  keyGenerator?: (context: RateLimitContext) => string;

  /** Skip function (return true to skip rate limiting) */
  skip?: (context: RateLimitContext) => boolean | Promise<boolean>;

  /** Handler when rate limit is exceeded */
  onRateLimitExceeded?: (context: RateLimitContext, result: RateLimitResult) => void;

  /** Custom store (default: in-memory) */
  store?: RateLimitStore;
}

/**
 * Rate limit context
 */
export interface RateLimitContext {
  /** User ID if authenticated */
  userId?: string;

  /** IP address */
  ip?: string;

  /** Request path */
  path?: string;

  /** Request method */
  method?: string;

  /** API key ID if using API key auth */
  apiKeyId?: string;

  /** Additional metadata */
  metadata?: Record<string, unknown>;
}

/**
 * Rate limit result
 */
export interface RateLimitResult {
  /** Whether the request is allowed */
  allowed: boolean;

  /** Remaining requests in current window */
  remaining: number;

  /** Total requests allowed per window */
  limit: number;

  /** Time until window resets (ms) */
  resetIn: number;

  /** Reset timestamp */
  resetAt: number;

  /** Current request count */
  current: number;
}

/**
 * Rate limit store interface
 */
export interface RateLimitStore {
  /** Increment counter and get current state */
  increment(key: string, windowMs: number): Promise<{ count: number; resetAt: number }>;

  /** Get current state without incrementing */
  get(key: string): Promise<{ count: number; resetAt: number } | null>;

  /** Reset counter for a key */
  reset(key: string): Promise<void>;
}

/**
 * In-memory rate limit store using sliding window
 */
export class InMemoryRateLimitStore implements RateLimitStore {
  private windows = new Map<string, { count: number; resetAt: number }>();
  private cleanupInterval: ReturnType<typeof setInterval> | null = null;

  constructor(cleanupIntervalMs: number = 60000) {
    // Periodic cleanup of expired windows
    this.cleanupInterval = setInterval(() => {
      const now = Date.now();
      for (const [key, window] of this.windows) {
        if (window.resetAt < now) {
          this.windows.delete(key);
        }
      }
    }, cleanupIntervalMs);
  }

  async increment(key: string, windowMs: number): Promise<{ count: number; resetAt: number }> {
    const now = Date.now();
    const existing = this.windows.get(key);

    if (existing && existing.resetAt > now) {
      // Window still valid, increment
      existing.count++;
      return { count: existing.count, resetAt: existing.resetAt };
    }

    // Start new window
    const newWindow = { count: 1, resetAt: now + windowMs };
    this.windows.set(key, newWindow);
    return newWindow;
  }

  async get(key: string): Promise<{ count: number; resetAt: number } | null> {
    const window = this.windows.get(key);
    if (!window || window.resetAt < Date.now()) {
      return null;
    }
    return window;
  }

  async reset(key: string): Promise<void> {
    this.windows.delete(key);
  }

  /**
   * Stop the cleanup interval
   */
  destroy(): void {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
      this.cleanupInterval = null;
    }
  }
}

/**
 * Default key generator (uses IP or user ID)
 */
function defaultKeyGenerator(context: RateLimitContext): string {
  if (context.userId) {
    return `user:${context.userId}`;
  }
  if (context.apiKeyId) {
    return `apikey:${context.apiKeyId}`;
  }
  if (context.ip) {
    return `ip:${context.ip}`;
  }
  return 'global';
}

/**
 * Create a rate limiter
 */
export function createRateLimiter(config: RateLimitConfig) {
  const store = config.store ?? new InMemoryRateLimitStore();
  const keyGenerator = config.keyGenerator ?? defaultKeyGenerator;

  return {
    /**
     * Check and consume a request
     */
    async check(context: RateLimitContext): Promise<RateLimitResult> {
      // Check if should skip
      if (config.skip) {
        const shouldSkip = await config.skip(context);
        if (shouldSkip) {
          return {
            allowed: true,
            remaining: config.maxRequests,
            limit: config.maxRequests,
            resetIn: config.windowMs,
            resetAt: Date.now() + config.windowMs,
            current: 0,
          };
        }
      }

      const key = keyGenerator(context);
      const { count, resetAt } = await store.increment(key, config.windowMs);

      const result: RateLimitResult = {
        allowed: count <= config.maxRequests,
        remaining: Math.max(0, config.maxRequests - count),
        limit: config.maxRequests,
        resetIn: Math.max(0, resetAt - Date.now()),
        resetAt,
        current: count,
      };

      if (!result.allowed && config.onRateLimitExceeded) {
        config.onRateLimitExceeded(context, result);
      }

      return result;
    },

    /**
     * Get current state without consuming
     */
    async peek(context: RateLimitContext): Promise<RateLimitResult> {
      const key = keyGenerator(context);
      const state = await store.get(key);

      if (!state) {
        return {
          allowed: true,
          remaining: config.maxRequests,
          limit: config.maxRequests,
          resetIn: config.windowMs,
          resetAt: Date.now() + config.windowMs,
          current: 0,
        };
      }

      return {
        allowed: state.count < config.maxRequests,
        remaining: Math.max(0, config.maxRequests - state.count),
        limit: config.maxRequests,
        resetIn: Math.max(0, state.resetAt - Date.now()),
        resetAt: state.resetAt,
        current: state.count,
      };
    },

    /**
     * Reset rate limit for a context
     */
    async reset(context: RateLimitContext): Promise<void> {
      const key = keyGenerator(context);
      await store.reset(key);
    },

    /**
     * Get the underlying store
     */
    getStore(): RateLimitStore {
      return store;
    },
  };
}

/**
 * Create rate limit middleware
 */
export function createRateLimitMiddleware(config: RateLimitConfig) {
  const limiter = createRateLimiter(config);

  return async (request: Request, context?: Partial<RateLimitContext>): Promise<{
    allowed: boolean;
    response?: Response;
    headers: Record<string, string>;
  }> => {
    // Extract context from request
    const fullContext: RateLimitContext = {
      ip: request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() 
        ?? request.headers.get('x-real-ip') 
        ?? undefined,
      path: new URL(request.url).pathname,
      method: request.method,
      ...context,
    };

    const result = await limiter.check(fullContext);

    // Build headers
    const headers: Record<string, string> = {
      'X-RateLimit-Limit': String(result.limit),
      'X-RateLimit-Remaining': String(result.remaining),
      'X-RateLimit-Reset': String(Math.ceil(result.resetAt / 1000)),
    };

    if (!result.allowed) {
      headers['Retry-After'] = String(Math.ceil(result.resetIn / 1000));

      return {
        allowed: false,
        headers,
        response: new Response(
          JSON.stringify({
            error: 'Rate limit exceeded',
            retryAfter: Math.ceil(result.resetIn / 1000),
          }),
          {
            status: 429,
            headers: {
              'Content-Type': 'application/json',
              ...headers,
            },
          }
        ),
      };
    }

    return { allowed: true, headers };
  };
}

/**
 * Common rate limit presets
 */
export const RateLimitPresets = {
  /** Standard API rate limit: 100 requests per minute */
  standard: {
    maxRequests: 100,
    windowMs: 60 * 1000,
  },

  /** Strict rate limit: 10 requests per minute */
  strict: {
    maxRequests: 10,
    windowMs: 60 * 1000,
  },

  /** Lenient rate limit: 1000 requests per minute */
  lenient: {
    maxRequests: 1000,
    windowMs: 60 * 1000,
  },

  /** Auth endpoints: 5 requests per minute */
  auth: {
    maxRequests: 5,
    windowMs: 60 * 1000,
  },

  /** Chat/AI endpoints: 20 requests per minute */
  chat: {
    maxRequests: 20,
    windowMs: 60 * 1000,
  },
} as const;
